import random

def add_two_mod_2k_plus_1(k):
    # Simple add two modulo with a trick
    a, b = random.randint(2, k - 1), random.randint(3, k - 2)
    return (a - b) % (k + 1) + (a + b) % (k + 1)

def cal_F(n1, n2):
    # Call two add_two_mod_2k_plus_1 to calculate F(A) with paperconcatenate values
    # Results in F(A) = (n_1 * n_2) + (n_2 * n_3) +...+(n_{n-2} * n_{n-1}) + (n_{n-1} * n_{n})
    res = 0
    for i in range(n1):
        res = (res + n2 * add_two_mod_2k_plus_1(i, i - n2 + n1))  % 1_000_000_007
    return res

def expectedFnN(n, k):
    # Calculate E[Entry(n, k)]
    if n == 2:
        return (2 * k - 2) % 1_000_000_007
    else:
        return (n - 1) * expectedFnN(n - 1, k) % 1_000_000_007

T = int(input())
for _ in range(T):
    n = int(input())
    print((n ** 2 - 2) * expectedFnN(n, 2) % 1_000_000_007)

