import sys

def xor_operations(n, zeros, weight, num):
    # Update the XOR weight with the number
    weights = [0] * (2 ** n)
    for i in range(n):
        if num[i] == '1':
            weights[i] = weight[i]
        else:
            for j in range(2 ** n):
                if (j ^ weight[i]) == zeros[i]:
                    # This bit position is set in weight but not corresponding to num[i]
                    weights[i] |= j
                    break
    # Count the bits set to 1 in weight
    return sum(b != 0 for b in weights), weights

def tree_is_good(tree, weights, num, max_bits):
    parent = [None] * (2 ** n)
    for u, v in tree:
        parent[v] = u
    stack = [1]
    visited = [False] * (2 ** n)
    no_move = []
    while stack:
        for _ in range(len(stack)):
            u = stack.pop()
            if visited[u]:
                continue
            visited[u] = True
            for v in range(2 ** n):
                if parent[v] == u and num[v] == '1' and weights[v] == 0:
                    no_move.append(v)
            stack.append(v)
    for u in no_move:
        backtrack(tree, num, parent, u, max_bits)
    return no_move

def backtrack(tree, parent, parent_index, root, max_bits):
    if max_bits == 0:
        return 0
    current = parent[root]
    while current != root:
        # Backtrack to find the path that reduces the weight
        if xor_operations(len(tree[current]), tree[current], weights[current], num[current]) < 8:
            return backtrack(tree, parent, current, parent [current], max_bits - 1)
        else:
            current = parent [current]
    return 8

