def preprocess_bfs_tree(graph):
    def bfs_tree(node, root, visited, parent):
        queue = [(node, root)]
        visited[node] = 1
        while queue:
            node, s = queue.pop(0)
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = 1
                    queue.append((neighbor, s))
                    parent[neighbor] = node
        return visited, parent

    visited, parent = bfs_tree(1, 1, [0] * (n + 1), [0] * (n + 1))
    bfs_tree_visited = defaultdict(int)
    bfs_tree_parent = defaultdict(int)

    for node in range(1, n + 1):
        bfs_tree_visited[parent[node]] += 1
        bfs_tree_parent[parent[node]] = node

    return visited, bfs_tree_visited, bfs_tree_parent

def pre_process(n, graph):
    visited, bfs_tree_visited, bfs_tree_parent = preprocess_bfs_tree(graph)

    def count_spannings(start, end):
