# Python program to find the number of ways to divide an array into segments with at most k distinct integers appearing exactly once.
import math

mod = 998244353

def fact(n):
    return math.factorial(n) % mod

modFact = [None] * (n+1)
for i in range(1, n+1):
    modFact[i] = fact(i) % mod

def mpow(x, n):
    ans = 1
    x = x % mod
    while (n > 0):
        if (n % 2):
            ans = (ans * x) % mod
        n = n // 2
        x = (x * x) % mod
    return ans % mod

class Solution:
    def solve(self, n, k):
        dp = [[0] * (k+1) for _ in range(n+1)]
        dp[0][0] = 1
        for i in range(1, n+1):
            for j in range(k+1):
                dp[i][j] = (dp[i-1][j] * fact(j)) % mod
            for j in range(k, 0, -1):
                dp[i][j] = (dp[i][j] - dp[i-1][j-1] + mod) % mod
        return dp[n][k]
sol = Solution()
