def update_tree(N, a, edges):
    parent = [i for i in range(N+1)]
    def find(x):
        if x != parent[x]:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_x] = root_y

    for u, v in edges:
        union(u, v)

    tree_map = defaultdict(int)
    for i, x in enumerate(a):
        root = find(i+1)
        tree_map[root] ^= x

    return len(tree_map) - len([1 for val, cnt in tree_map.items() if cnt % 2 == 1]) 

