from math import comb

mod = 998244353

def count_divisions(n, k):
    # Initialize variables
    heights = [0] * (k + 1)
    dp = [0] * (k + 1)

    # (0, 1) points to index of how many elements in the smallest segment
    dp[0] = 1

    for i in range(1, n + 1):
        heights[i % k] += 1
        dp.height[i % k] = dp[i % k - 1]  # No duplicates less than this segment

        man = heights[i % k]
        if man != 0:
            for l in range(1, k):
                dp[l] = (dp[l] - dp[l - man]) % mod
        else:
            for l in range(1, min(k, heights[i % k]) + 1):
                dp[l] = (dp[l] * (comb(1 + l, l)) % mod) % mod

    return sum(dp)

