from math import gcd
from functools import reduce

MOD = 998244353

def lcm(a, b):
    return a * b // gcd(a, b)

def combinations(n, k):
    return reduce(lambda x, y: x * y, range(1, k + 2)) // reduce(lambda x, y: x * y, range(1, k + 1))

def solve(n, k, A):
    c = 0
    comb_reduced = combinations(n - 1, k)
    for i in range(1, n):
        for j in range(i + 1, n):
            left = A[:i]
            right = A[j:]
            value = 0
            for a in left:
                if a not in right:
                    value += 1
            value %= MOD
            comb_reduced_numerator = combinations(len(left), value) * combinations(len(right), k - value)
            c += min(comb_reduced, comb_reduced_numerator) % MOD
            c %= MOD
            comb_reduced //= gcd(comb_reduced, value)
    return c

