from collections import defaultdict

def balance_char_count(s):
    count = defaultdict(int)
    for char in s:
        count[char] += 2
    return tuple(count.values())

def calc_outcome(s, l, r):
    balance_before = balance_char_count(s[l-1:r])
    result = True
    char_count = defaultdict(lambda: -1)

    for char in s[l-1:r]:
        if char_count[char] >= 0:
            # Character appears more than once
            result = False
        char_count[char] += 1

    if result:
        first_perm = s[l-1:r][0]
        second_perm = ''
        for char in s[l-1:r]:
            if char == first_perm:
                second_perm += first_perm
            else:
                second_perm += char.count(char) % 2 * first_perm
        result = not (second_perm in s[l-1:r])

    return tuple(balance_before), tuple(list(char_count.values())), result

def analyze_games(s, n):
    winners = []
    for i in range(n):
        l, r = map(int, input().split(" "))
        outcome, balance_outcome, result_count = calc_outcome(s, l, r)
        winners.append("Alice" if result_count else "Bob")
    return winners

